UPDATE lessons SET title='Year 4, Week 21, Lesson 2: Modified net games', data=json_patch(data,'{"child_mission":"Modified net games change court size, bounce rules or catch-allowed so more students succeed and stay active.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nSuggest one modification for a classmate who finds overhead hits hard.\n\nFEEDBACK\nCatch-and-throw; underarm only; partner assist — any inclusive idea.\n\nWATCH FOR\nRefusing all modifications excludes learners.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nPlay two modified versions. Vote which felt fairest and why.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Modified net games change court size, bounce rules or catch-allowed so more students succeed and stay active.","lesson_number":2,"lesson_role":"Practise and apply","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-MSP-01"],"parent_notes":"Parent: Marking guidance for the independent task: Play two modified versions. Vote which felt fairest and why. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: Catch-and-thr